import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { adminService } from '../../services/adminService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage } from '../../utils/helpers';

const AdminDashboard = () => {
  const [dashboardData, setDashboardData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await adminService.getDashboard();
      setDashboardData(response.data);
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LoadingSpinner message="Loading admin dashboard..." />;
  }

  if (error) {
    return (
      <div className="dashboard-page">
        <div className="container">
          <div className="error-container">
            <div className="error-message">
              <h2>Error Loading Dashboard</h2>
              <p>{error}</p>
              <button onClick={loadDashboardData} className="btn btn-primary">
                Try Again
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-page admin-dashboard">
      <div className="container">
        <div className="dashboard-header">
          <h1>Admin Dashboard</h1>
          <p>Manage food truck vendors and applications</p>
        </div>

        {/* Stats Cards */}
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-icon">🚚</div>
            <div className="stat-content">
              <h3>{dashboardData?.totalVendors || 0}</h3>
              <p>Total Vendors</p>
            </div>
          </div>

          <div className="stat-card">
            <div className="stat-icon">📄</div>
            <div className="stat-content">
              <h3>{dashboardData?.totalApplications || 0}</h3>
              <p>Total Applications</p>
            </div>
          </div>

          <div className="stat-card pending">
            <div className="stat-icon">⏳</div>
            <div className="stat-content">
              <h3>{dashboardData?.pendingApplications || 0}</h3>
              <p>Pending Review</p>
            </div>
          </div>

          <div className="stat-card approved">
            <div className="stat-icon">✅</div>
            <div className="stat-content">
              <h3>{dashboardData?.approvedApplications || 0}</h3>
              <p>Approved</p>
            </div>
          </div>
        </div>

        {/* Quick Actions */}
        <div className="quick-actions">
          <h3>Quick Actions</h3>
          <div className="actions-grid">
            <Link to="/admin/vendors" className="action-card">
              <div className="action-icon">🚚</div>
              <h4>Manage Vendors</h4>
              <p>View and manage all registered food truck vendors</p>
            </Link>

            <Link to="/admin/applications" className="action-card">
              <div className="action-icon">📋</div>
              <h4>Review Applications</h4>
              <p>Process and review license applications</p>
            </Link>

            <Link to="/admin/applications?status=SUBMITTED" className="action-card urgent">
              <div className="action-icon">🔥</div>
              <h4>Pending Reviews</h4>
              <p>{dashboardData?.pendingApplications || 0} applications waiting for review</p>
            </Link>

            <div className="action-card info">
              <div className="action-icon">📊</div>
              <h4>System Status</h4>
              <p>All systems operational</p>
            </div>
          </div>
        </div>

        {/* Application Status Breakdown */}
        <div className="status-breakdown">
          <h3>Application Status Breakdown</h3>
          <div className="status-chart">
            <div className="chart-item">
              <div className="chart-bar">
                <div className="bar-fill pending" style={{height: `${(dashboardData?.pendingApplications || 0) * 10}%`}}></div>
              </div>
              <span className="chart-label">Pending ({dashboardData?.pendingApplications || 0})</span>
            </div>
            
            <div className="chart-item">
              <div className="chart-bar">
                <div className="bar-fill approved" style={{height: `${(dashboardData?.approvedApplications || 0) * 10}%`}}></div>
              </div>
              <span className="chart-label">Approved ({dashboardData?.approvedApplications || 0})</span>
            </div>
            
            <div className="chart-item">
              <div className="chart-bar">
                <div className="bar-fill rejected" style={{height: `${(dashboardData?.rejectedApplications || 0) * 10}%`}}></div>
              </div>
              <span className="chart-label">Rejected ({dashboardData?.rejectedApplications || 0})</span>
            </div>
          </div>
        </div>

        {/* Recent Activity */}
        <div className="recent-activity">
          <div className="section-header">
            <h3>Recent Activity</h3>
            <Link to="/admin/applications">View All Applications</Link>
          </div>
          
          <div className="activity-placeholder">
            <p>Activity tracking will be available in the next update.</p>
            <p>Currently showing application statistics above.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
